import React, { useState, useRef, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { paperAPI } from '../utils/api';
import StatusBadge from './StatusBadge';

export default function ScanModal({ onClose }) {
  const nav = useNavigate();
  const [tab, setTab] = useState('camera'); // camera or manual
  const [ref, setRef]       = useState('');
  const [error, setError]   = useState('');
  const [result, setResult] = useState(null);
  const [stream, setStream] = useState(null);
  const videoRef = useRef();
  const canvasRef = useRef();

  useEffect(() => {
    if (tab === 'camera') {
      startCamera();
    } else {
      stopCamera();
    }
    return () => stopCamera();
  }, [tab]);

  const startCamera = async () => {
    try {
      const s = await navigator.mediaDevices.getUserMedia({ 
        video: { facingMode: 'environment' } 
      });
      setStream(s);
      if (videoRef.current) videoRef.current.srcObject = s;
      // Start scanning
      scanForCode();
    } catch {
      setError('Camera not available. Use manual entry instead.');
      setTab('manual');
    }
  };

  const stopCamera = () => {
    if (stream) stream.getTracks().forEach(t => t.stop());
    setStream(null);
  };

  const scanForCode = () => {
    if (!videoRef.current) return;
    const canvas = canvasRef.current;
    if (!canvas) return;

    const ctx = canvas.getContext('2d');
    const video = videoRef.current;

    const scan = () => {
      if (video.readyState === video.HAVE_ENOUGH_DATA) {
        canvas.width = video.videoWidth;
        canvas.height = video.videoHeight;
        ctx.drawImage(video, 0, 0);

        // Try to read barcode using jsBarcode via canvas
        try {
          const imageData = ctx.getImageData(0, 0, canvas.width, canvas.height);
          // Simple QR code detection by looking for black/white patterns
          // For production, use a proper QR/barcode library
          const decoded = detectCode(imageData);
          if (decoded) {
            setRef(decoded);
            stopCamera();
            return;
          }
        } catch (e) {
          // Continue scanning
        }
      }
      if (stream) requestAnimationFrame(scan);
    };
    scan();
  };

  const detectCode = (imageData) => {
    // Simple QR/barcode detection - looks for numeric pattern
    // In production, use a library like jsQR or dynamsoft barcode reader
    const data = imageData.data;
    let text = '';

    // This is a placeholder - real implementation would use proper QR/barcode detection
    // For now, we'll rely on manual input or external library
    return null;
  };

  const lookup = async (e) => {
    e.preventDefault();
    if (!ref) return;
    setError(''); setResult(null);
    try {
      const r = await paperAPI.scan(ref);
      setResult(r.data.paper);
    } catch (err) {
      setError(err.response?.data?.error || 'Not found.');
    }
  };

  const goTo = () => { nav(`/paper/${result.id}`); onClose(); };

  return (
    <div className="overlay" onClick={e => e.target === e.currentTarget && onClose()}>
      <div className="modal">
        <div className="modal-head">
          <span className="modal-title">📷 Scan / Lookup</span>
          <button className="btn btn-outline btn-sm" onClick={onClose}>✕</button>
        </div>
        <div className="modal-body">
          <div style={{ display: 'flex', gap: 8, marginBottom: 16, borderBottom: '1px solid var(--border)' }}>
            <button 
              className={`btn btn-sm ${tab === 'camera' ? 'btn-navy' : 'btn-outline'}`}
              onClick={() => setTab('camera')}
              style={{ borderBottom: tab === 'camera' ? '3px solid var(--navy)' : 'none' }}
            >
              📷 Camera
            </button>
            <button 
              className={`btn btn-sm ${tab === 'manual' ? 'btn-navy' : 'btn-outline'}`}
              onClick={() => setTab('manual')}
              style={{ borderBottom: tab === 'manual' ? '3px solid var(--navy)' : 'none' }}
            >
              ✏️ Manual
            </button>
          </div>

          {error && <div className="alert a-err">{error}</div>}

          {tab === 'camera' && (
            <div style={{ marginBottom: 16 }}>
              <video 
                ref={videoRef} 
                style={{ 
                  width: '100%', 
                  borderRadius: 8, 
                  backgroundColor: '#000',
                  maxHeight: 300
                }} 
                autoPlay 
                playsInline
              />
              <canvas ref={canvasRef} style={{ display: 'none' }} />
              <p style={{ fontSize: 12, color: 'var(--t2)', marginTop: 8, textAlign: 'center' }}>
                Point camera at QR code or barcode
              </p>
            </div>
          )}

          {tab === 'manual' && (
            <form onSubmit={lookup} style={{ display:'flex', gap:8, marginBottom: 16 }}>
              <input 
                className="inp" 
                type="text" 
                placeholder="Enter Ref Code (e.g. 1, 25, 152)"
                value={ref} 
                onChange={e => setRef(e.target.value)} 
                required 
              />
              <button type="submit" className="btn btn-navy" style={{ whiteSpace:'nowrap' }}>
                Look Up
              </button>
            </form>
          )}

          {tab === 'camera' && ref && (
            <div style={{ marginBottom: 16 }}>
              <p style={{ fontSize: 12, color: 'var(--t2)' }}>Detected: <strong>{ref}</strong></p>
              <button onClick={lookup} className="btn btn-navy" style={{ width: '100%' }}>
                Look Up Code
              </button>
            </div>
          )}

          {result && (
            <div className="card mt4">
              <div className="card-body">
                <div className="alert a-ok mb2">✅ Paper found!</div>
                <table style={{ width:'100%' }}>
                  <tbody>
                    {[
                      ['Ref', <span className="mono" style={{fontSize:20,fontWeight:800,color:'var(--navy)'}}>#{result.ref_code}</span>],
                      ['Title', result.title],
                      ['Origin', result.origin],
                      ['Status', <StatusBadge action={result.status_action} dept={result.status_dept} />],
                    ].map(([k,v]) => (
                      <tr key={k} style={{ borderBottom:'1px solid var(--border)' }}>
                        <td style={{ padding:'8px 0', fontWeight:600, fontSize:11, color:'var(--t2)', width:70, textTransform:'uppercase' }}>{k}</td>
                        <td style={{ padding:'8px 0' }}>{v}</td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            </div>
          )}
        </div>
        <div className="modal-foot">
          <button className="btn btn-outline" onClick={onClose}>Close</button>
          {result && <button className="btn btn-navy" onClick={goTo}>View Full Details →</button>}
        </div>
      </div>
    </div>
  );
}
